  "filename": "page_task.js",
  "content": "/* page_task.js – registers the Task page UI */
(function () {
  // Ensure the global register function exists
  if (!window.ForgeAI || typeof window.ForgeAI.registerPage !== 'function') {
    console.error('ForgeAI registerPage not available');
    return;
  }

  const ACCENT_COLOR = '#336699'; // from spec.theme.accent_colour

  // Helper to create elements with optional classes & attrs
  function el(tag, options = {}, children = []) {
    const node = document.createElement(tag);
    if (options.class) node.className = options.class;
    if (options.id) node.id = options.id;
    if (options.attrs) {
      Object.entries(options.attrs).forEach(([k, v]) => node.setAttribute(k, v));
    }
    if (options.text) node.textContent = options.text;
    children.forEach((c) => node.appendChild(c));
    return node;
  }

  // Simple toast (replace with a better UI if needed)
  function toast(message, type = 'info') {
    const toast = el('div', { class: `toast toast-${type}` }, [document.createTextNode(message)]);
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
  }

  // Render function registered with ForgeAI
  async function renderTaskPage(ctx) {
    const { root, api } = ctx;
    root.innerHTML = '';

    // Header
    const header = el('div', { class: 'page-header' }, [
      el('h2', { text: 'Tasks' }),
      el('button', { class: 'btn btn-primary', text: '+ New Task', attrs: { type: 'button' } })
    ]);
    root.appendChild(header);

    // Table container
    const tableContainer = el('div', { class: 'task-table-container' });
    root.appendChild(tableContainer);

    // Modal placeholder (will be added/removed dynamically)
    const modalOverlay = el('div', { class: 'modal-overlay hidden' });
    document.body.appendChild(modalOverlay);

    // Load and render tasks
    async function loadTasks() {
      tableContainer.innerHTML = '';
      const loading = el('div', { class: 'loading', text: 'Loading tasks...' });
      tableContainer.appendChild(loading);
      try {
        const resp = await api('/tasks', { method: 'GET' });
        if (!resp.success) throw new Error('API error');
        const tasks = resp.data;
        renderTable(tasks);
      } catch (e) {
        console.error(e);
        tableContainer.innerHTML = '';
        const err = el('div', { class: 'error', text: 'Failed to load tasks.' });
        tableContainer.appendChild(err);
      }
    }

    function renderTable(tasks) {
      tableContainer.innerHTML = '';
      if (tasks.length === 0) {
        const empty = el('div', { class: 'empty-state', text: 'No tasks yet. Click "+ New Task" to add one.' });
        tableContainer.appendChild(empty);
        return;
      }

      const table = el('table', { class: 'task-table' });
      const thead = el('thead', {}, [
        el('tr', {}, [
          el('th', { text: 'Title' }),
          el('th', { text: 'Due Date' }),
          el('th', { text: 'Priority' }),
          el('th', { text: 'Completed' }),
          el('th', { text: 'Actions' })
        ])
      ]);
      const tbody = el('tbody');

      tasks.forEach((task) => {
        const tr = el('tr', {});
        tr.appendChild(el('td', { text: task.title }));
        tr.appendChild(el('td', { text: task.due_date }));
        tr.appendChild(el('td', { text: task.priority }));
        const completedCheckbox = el('input', { attrs: { type: 'checkbox' }, class: 'completed-toggle' });
        completedCheckbox.checked = !!task.completed;
        completedCheckbox.addEventListener('change', () => toggleCompleted(task.id, completedCheckbox.checked));
        tr.appendChild(el('td', {}, [completedCheckbox]));

        // Actions: edit, delete
        const editBtn = el('button', { class: 'btn btn-sm btn-secondary', text: 'Edit', attrs: { type: 'button' } });
        editBtn.addEventListener('click', () => openForm(task));
        const delBtn = el('button', { class: 'btn btn-sm btn-danger', text: 'Delete', attrs: { type: 'button' } });
        delBtn.addEventListener('click', () => deleteTask(task.id));
        tr.appendChild(el('td', {}, [editBtn, delBtn]));
        tbody.appendChild(tr);
      });

      table.appendChild(thead);
      table.appendChild(tbody);
      tableContainer.appendChild(table);
    }

    async function toggleCompleted(id, completed) {
      try {
        await api(`/tasks/${id}`, {
          method: 'PATCH',
          json: { completed }
        });
        toast('Task updated', 'success');
        loadTasks();
      } catch (e) {
        console.error(e);
        toast('Failed to update task', 'error');
      }
    }

    async function deleteTask(id) {
      if (!confirm('Delete this task?')) return;
      try {
        await api(`/tasks/${id}`, { method: 'DELETE' });
        toast('Task deleted', 'success');
        loadTasks();
      } catch (e) {
        console.error(e);
        toast('Failed to delete task', 'error');
      }
    }

    // Form handling (create / edit)
    function openForm(task = null) {
      modalOverlay.innerHTML = '';
      modalOverlay.classList.remove('hidden');

      const isEdit = !!task;
      const titleText = isEdit ? 'Edit Task' : 'New Task';

      const form = el('form', { class: 'task-form' }, [
        el('h3', { text: titleText }),
        el('label', { text: 'Title' }),
        el('input', { attrs: { type: 'text', required: true, name: 'title' }, class: 'input' }),
        el('label', { text: 'Due Date' }),
        el('input', { attrs: { type: 'date', required: true, name: 'due_date' }, class: 'input' }),
        el('label', { text: 'Priority' }),
        el('select', { attrs: { name: 'priority' }, class: 'input' }, [
          el('option', { attrs: { value: 'Low' }, text: 'Low' }),
          el('option', { attrs: { value: 'Medium' }, text: 'Medium' }),
          el('option', { attrs: { value: 'High' }, text: 'High' })
        ]),
        el('label', { text: 'Completed' }),
        el('input', { attrs: { type: 'checkbox', name: 'completed' }, class: 'input' }),
        el('div', { class: 'form-actions' }, [
          el('button', { class: 'btn btn-primary', text: isEdit ? 'Save' : 'Create', attrs: { type: 'submit' } }),
          el('button', { class: 'btn btn-secondary', text: 'Cancel', attrs: { type: 'button' } })
        ])
      ]);

      // Prefill if editing
      if (isEdit) {
        form.title.value = task.title;
        form.due_date.value = task.due_date;
        form.priority.value = task.priority;
        form.completed.checked = !!task.completed;
      }

      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const payload = {
          title: form.title.value.trim(),
          due_date: form.due_date.value,
          priority: form.priority.value,
          completed: form.completed.checked
        };
        try {
          if (isEdit) {
            await api(`/tasks/${task.id}`, { method: 'PATCH', json: payload });
            toast('Task updated', 'success');
          } else {
            await api('/tasks', { method: 'POST', json: payload });
            toast('Task created', 'success');
          }
          closeModal();
          loadTasks();
        } catch (err) {
          console.error(err);
          toast('Failed to save task', 'error');
        }
      });

      form.querySelector('.btn-secondary').addEventListener('click', closeModal);

      const modalContent = el('div', { class: 'modal-content' }, [form]);
      modalOverlay.appendChild(modalContent);
    }

    function closeModal() {
      modalOverlay.classList.add('hidden');
      modalOverlay.innerHTML = '';
    }

    // Bind New Task button
    header.querySelector('button.btn-primary').addEventListener('click', () => openForm());

    // Initial load
    loadTasks();
  }

  // Register the page under the slug "task"
  window.ForgeAI.registerPage('task', renderTaskPage);
})();
"
